CREATE TABLE "User" ("id" TEXT NOT NULL, "username" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Credential" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Credential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Resume" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fileName" TEXT NOT NULL, "contentType" TEXT NOT NULL, "extractedText" TEXT NOT NULL, "disclosureConsent" BOOLEAN NOT NULL, "noticeVersion" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Resume_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Interview" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "resumeId" TEXT NOT NULL, "position" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'CREATED', "currentIndex" INTEGER NOT NULL DEFAULT 0, "questionCount" INTEGER NOT NULL DEFAULT 5, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Interview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Turn" ("id" TEXT NOT NULL, "interviewId" TEXT NOT NULL, "sequence" INTEGER NOT NULL, "answerText" TEXT NOT NULL, "questionText" TEXT, "score" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Turn_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Report" ("id" TEXT NOT NULL, "interviewId" TEXT NOT NULL, "score" INTEGER NOT NULL, "strengths" JSONB NOT NULL, "weaknesses" JSONB NOT NULL, "feedback" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Report_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IdempotencyRecord" ("key" TEXT NOT NULL, "userId" TEXT NOT NULL, "response" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "IdempotencyRecord_pkey" PRIMARY KEY ("key"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE UNIQUE INDEX "Credential_userId_key" ON "Credential"("userId"); CREATE UNIQUE INDEX "Turn_interviewId_sequence_key" ON "Turn"("interviewId", "sequence"); CREATE UNIQUE INDEX "Report_interviewId_key" ON "Report"("interviewId");
ALTER TABLE "Credential" ADD CONSTRAINT "Credential_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Resume" ADD CONSTRAINT "Resume_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Interview" ADD CONSTRAINT "Interview_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Interview" ADD CONSTRAINT "Interview_resumeId_fkey" FOREIGN KEY ("resumeId") REFERENCES "Resume"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Turn" ADD CONSTRAINT "Turn_interviewId_fkey" FOREIGN KEY ("interviewId") REFERENCES "Interview"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Report" ADD CONSTRAINT "Report_interviewId_fkey" FOREIGN KEY ("interviewId") REFERENCES "Interview"("id") ON DELETE CASCADE ON UPDATE CASCADE;
